import random
import time

class NaiveArray:
    def __init__(self, arr):
        self.arr = arr

    def update(self, index, value):
        if 0 <= index < len(self.arr):
            self.arr[index] = value
        else:
            raise IndexError("Index out of bounds")

    def query(self, left, right):
        if 0 <= left <= right < len(self.arr):
            return sum(self.arr[left:right+1])
        else:
            raise IndexError("Query range out of bounds")


class SegmentTree:
    def __init__(self, arr):
        self.arr = arr
        self.n = len(arr)
        self.tree = [0] * (4 * self.n)  # Allocate enough space for the tree
        self.build(0, 0, self.n - 1)

    def build(self, node, start, end):
        if start == end:
            self.tree[node] = self.arr[start]
        else:
            mid = (start + end) // 2
            self.build(2 * node + 1, start, mid)
            self.build(2 * node + 2, mid + 1, end)
            self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]

    def update(self, index, value):
        self._update(0, 0, self.n - 1, index, value)

    def _update(self, node, start, end, index, value):
        if start == end:
            self.arr[index] = value
            self.tree[node] = value
        else:
            mid = (start + end) // 2
            if start <= index <= mid:
                self._update(2 * node + 1, start, mid, index, value)
            else:
                self._update(2 * node + 2, mid + 1, end, index, value)
            self.tree[node] = self.tree[2 * node + 1] + self.tree[2 * node + 2]

    def query(self, left, right):
        return self._query(0, 0, self.n - 1, left, right)

    def _query(self, node, start, end, left, right):
        if right < start or end < left:
            return 0
        if left <= start and end <= right:
            return self.tree[node]
        mid = (start + end) // 2
        return self._query(2 * node + 1, start, mid, left, right) + \
               self._query(2 * node + 2, mid + 1, end, left, right)


def benchmark(n, q):
    arr = [random.randint(1, 100) for _ in range(n)]
    tree = SegmentTree(arr)

    # Generate queries and updates
    updates = []
    queries = []
    for _ in range(q):
        update_index = random.randint(0, n - 1)
        update_value = random.randint(1, 100)
        updates.append((update_index, update_value))
        left = random.randint(0, n - 1)
        right = random.randint(left, n - 1)
        queries.append((left, right))

