    start_time = time.time()
    for update_index, update_value in updates:
        tree.update(update_index, update_value)
    for left, right in queries:
        tree.query(left, right)
    end_time = time.time()
    segment_tree_time = end_time - start_time

    print(f"N = {n}, Q = {q}")
    print(f"Naive Array Time: {naive_time:.6f} seconds")
    print(f"Segment Tree Time: {segment_tree_time:.6f} seconds")


if __name__ == "__main__":
